import {safe} from './experience.js';
let audio,dock,objectUrl='',currentId='';
export function audioReview(a){if(a.id!=='burial-untrue'&&!a.audioReview?.src)return '';return `<section class="audio-review"><div><span class="eyebrow">REVIEW EM ÁUDIO</span><h2>Uma outra forma de ouvir.</h2><p>${a.audioReview?.src?'Narração com voz sintética.':'Espaço reservado para a gravação desta review.'}</p><a class="text-link" href="#transcricao" data-transcript>Ir para o texto ↓</a></div>${a.audioReview?.src?`<button class="solid" data-audio-src="${safe(a.audioReview.src)}">Ouvir review ▶</button>`:`<label class="audio-file">Testar com um áudio local<input type="file" accept="audio/*" data-audio-file><small>Somente neste navegador. O arquivo não é enviado.</small></label>`}<p class="audio-message" role="status"></p></section>`;}
function ensurePlayer(){if(audio)return;dock=document.createElement('aside');dock.className='audio-dock';dock.setAttribute('aria-label','Player da review');dock.hidden=true;dock.innerHTML='<div><a class="audio-dock-title"></a><span class="small">Review em áudio</span></div><audio controls preload="metadata"></audio><button class="audio-dismiss" aria-label="Fechar e parar áudio">×</button><p role="status"></p>';document.body.append(dock);audio=dock.querySelector('audio');dock.querySelector('.audio-dismiss').onclick=()=>{audio.pause();audio.removeAttribute('src');audio.load();dock.hidden=true;document.body.classList.remove('has-audio');if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';currentId='';if(navigator.mediaSession)navigator.mediaSession.metadata=null;};audio.addEventListener('error',()=>{dock.querySelector('[role=status]').textContent='Não foi possível reproduzir este áudio. Tente outro formato.';});audio.addEventListener('play',()=>{if(navigator.mediaSession)navigator.mediaSession.playbackState='playing';});audio.addEventListener('pause',()=>{if(navigator.mediaSession)navigator.mediaSession.playbackState='paused';});}
export function bindAudio(root,a){const area=root.querySelector('.audio-review');if(!area)return;
 const play=async(src,local=false)=>{ensurePlayer();if(objectUrl&&objectUrl!==src)URL.revokeObjectURL(objectUrl);objectUrl=local?src:'';if(currentId!==a.id||audio.src!==new URL(src,location.href).href){audio.src=src;currentId=a.id;}dock.querySelector('.audio-dock-title').textContent=a.title+' — '+a.artist;dock.querySelector('.audio-dock-title').href='#album/'+a.id;dock.querySelector('[role=status]').textContent='';dock.hidden=false;document.body.classList.add('has-audio');
  if('mediaSession'in navigator&&'MediaMetadata'in window){navigator.mediaSession.metadata=new MediaMetadata({title:'Review: '+a.title,artist:'meeting.points',album:a.artist,artwork:[{src:new URL(a.cover,location.href).href}]});for(const [name,fn]of Object.entries({play:()=>audio.play().catch(()=>{}),pause:()=>audio.pause(),seekbackward:e=>{audio.currentTime=Math.max(0,audio.currentTime-(e.seekOffset||10));},seekforward:e=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,audio.currentTime+(e.seekOffset||10));}})){try{navigator.mediaSession.setActionHandler(name,fn);}catch{}}}
  try{await audio.play();area.querySelector('.audio-message').textContent=local?'Teste local: este áudio não é a gravação publicada da review.':'';}catch{area.querySelector('.audio-message').textContent='Use o botão de reprodução no player. Se não funcionar, escolha outro arquivo.';}
 };
 area.querySelector('[data-audio-src]')?.addEventListener('click',e=>play(e.currentTarget.dataset.audioSrc));
 area.querySelector('[data-audio-file]')?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>200*1024*1024){area.querySelector('.audio-message').textContent='Escolha um arquivo de até 200 MB.';return;}play(URL.createObjectURL(file),true);});
 area.querySelector('[data-transcript]').addEventListener('click',e=>{e.preventDefault();const text=root.querySelector('.detail-copy');text.tabIndex=-1;text.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});text.focus({preventScroll:true});});
}
